2	import { Block, Text } from "@prototyp/skeletor";
3	import type { UserProfile } from "@unomed/react-native-matrix-sdk";
4	import { format, isToday } from "date-fns";
5	import { MatrixCore } from "modules/matrix-client/services/MatrixCore";
6	import { useEffect, useState } from "react";
7	import { AppBottomSheet } from "shared/components/bottom-sheet";
8	import { Colors, TextSize } from "shared/styles";
9	import { UserProfileImage } from "../user-profile-image";
10	
11	interface RowProps {
12	  userId: string;
13	  timestamp: number | null;
14	}
15	
16	const SeenByRow: React.FC<RowProps> = ({ userId, timestamp }) => {
17	  const [profile, setProfile] = useState<UserProfile | null>(null);
18	  const displayName =
19	    profile?.displayName ?? userId.replace("@", "").split(":")[0];
20	
21	  useEffect(() => {
22	    MatrixCore.getClient().getProfile(userId).then(setProfile).catch();
23	  }, [userId]);
24	
25	  return (
26	    <Block
27	      flexDirection="row"
28	      align="center"
29	      gap={12}
30	      paddings={{ paddingVertical: 12 }}
31	      border={{ borderBottomWidth: 1, borderColor: Colors.white5 }}
32	    >
33	      <UserProfileImage user={profile} width={36} height={36} />
34	      <Block flex={1} gap={2}>
35	        <Text color={Colors.white} font="InstrumentSans-Bold">
36	          {displayName}
37	        </Text>
38	        <Text
39	          size={TextSize.small}
40	          color={Colors.white50}
41	          font="InstrumentSans-Regular"
42	        >
43	          {userId}
44	        </Text>
45	      </Block>
46	      {!!timestamp && (
47	        <Text
48	          size={TextSize.small}
49	          color={Colors.white50}
50	          font="InstrumentSans-Regular"
51	        >
52	          {isToday(timestamp)
53	            ? format(timestamp, "HH:mm")
54	            : format(timestamp, "MMM d, HH:mm")}
55	        </Text>
56	      )}
57	    </Block>
58	  );
59	};
