1	import { BottomSheetView } from "@gorhom/bottom-sheet";
2	import { Block, Text } from "@prototyp/skeletor";
3	import { RecoveryState } from "@unomed/react-native-matrix-sdk";
4	import { AuthService } from "modules/auth/service/AuthService";
5	import { EncryptionService } from "modules/encryption/service/EncryptionService";
6	import { NavigationContainerRef } from "modules/navigation/const";
7	import { useCallback, useEffect, useRef, useState } from "react";
8	import { Image } from "react-native";
9	import Toast from "react-native-toast-message";
10	import { Button, Loading } from "shared/components";
11	import {
12	  AppBottomSheet,
13	  type AppBottomSheetRef,
14	} from "shared/components/bottom-sheet";
15	import { usePreventSwipeBack } from "shared/hooks";
16	import { Colors, TextSize } from "shared/styles";
17	import { offlineToastHelper } from "shared/utils";
18	
19	interface Props {
20	  isBottomSheetOpen: boolean;
21	  setIsBottomSheetOpen: () => void;
22	}
23	
24	export const SignOutBottomSheet: React.FC<Props> = ({
25	  isBottomSheetOpen,
26	  setIsBottomSheetOpen,
27	}) => {
28	  const sheetRef = useRef<AppBottomSheetRef>(null);
29	  const [backupState, setBackupState] = useState<MappedBackupState>("unknown");
30	  const [recoveryState, setRecoveryState] = useState<RecoveryState>(
31	    RecoveryState.Unknown,
32	  );
33	  const isBackupEnabled =
34	    backupState === "enabled" ||
35	    (backupState === "unknown" &&
36	      (recoveryState === RecoveryState.Enabled ||
37	        recoveryState === RecoveryState.Incomplete));
38	  const [showBackupSetUpWarning, setShowBackupSetUpWarning] = useState(false);
39	  const [isSigningOut, setIsSigningOut] = useState(false);
40	
41	  const signOut = async () => {
42	    try {
43	      setIsSigningOut(true);
44	      await AuthService.logout();
45	      handleCancel();
46	      NavigationContainerRef.reset({
47	        index: 0,
48	        routes: [{ name: "splash" }],
49	      });
50	      Toast.show({
51	        type: "success",
52	        text1: "Successfully signed out",
53	      });
54	    } catch (error) {
55	      console.error("Failed to logout: ", error);
56	      offlineToastHelper("Failed to sign out");
57	    } finally {
58	      setIsSigningOut(false);
59	    }
60	  };
61	
62	  const handleClose = useCallback(() => {
63	    setIsBottomSheetOpen();
64	    setShowBackupSetUpWarning(false);
65	  }, [setIsBottomSheetOpen]);
66	
67	  const handleCancel = useCallback(() => {
68	    sheetRef.current?.close();
69	  }, []);
70	
71	  const handleSettings = useCallback(() => {
72	    handleCancel();
73	    NavigationContainerRef.navigate("encryption");
74	  }, [handleCancel]);
75	
76	  const handleSignOut = useCallback(() => {
77	    if (!isBackupEnabled) {
78	      setShowBackupSetUpWarning(true);
79	      return;
80	    }
81	
82	    signOut();
83	  }, [signOut]);
84	
85	  usePreventSwipeBack(isBottomSheetOpen);
86	
87	  useEffect(() => {
88	    const listener = EncryptionService.subscribeToBackupState((state) => {
89	      setBackupState(state);
90	    });
91	
92	    return () => {
93	      listener.cancel();
94	    };
95	  }, []);
96	
97	  useEffect(() => {
98	    const listener = EncryptionService.subscribeToRecoveryState((state) => {
99	      setRecoveryState(state);
100	    });
101	
102	    return () => {
103	      listener.cancel();
104	    };
105	  }, []);
106	
107	  return (
108	    <>
109	      {isSigningOut ? <Loading text="Signing out..." /> : null}
110	      <AppBottomSheet
111	        ref={sheetRef}
112	        isOpen={isBottomSheetOpen}
113	        onClose={handleClose}
114	      >
115	        <BottomSheetView>
116	          {showBackupSetUpWarning ? (
117	            <Block
118	              paddings={{
119	                paddingHorizontal: 20,
120	                paddingBottom: 20,
121	              }}
122	              gap={40}
123	              align="center"
124	            >
125	              <Image source={require("assets/images/key.png")} />
126	              <Block gap={8} align="center">
127	                <Text size={TextSize.large} color={Colors.white}>
128	                  Recovery not set up
129	                </Text>
130	                <Text font="InstrumentSans-Regular" textAlign="center">
131	                  You are about to sign out of your last session. If you sign
132	                  out now, you will lose access to your encrypted messages.
133	                </Text>
134	              </Block>
135	              <Block gap={12} width="100%" paddings={[0, 52]}>
136	                <Button.Outline onPress={handleSettings}>
137	                  Settings
138	                </Button.Outline>
139	                <Button.Warning onPress={signOut}>
140	                  Sign out anyway
141	                </Button.Warning>
142	              </Block>
143	            </Block>
144	          ) : (
145	            <Block
146	              paddings={{
147	                paddingHorizontal: 20,
148	                paddingBottom: 20,
149	              }}
150	              gap={40}
151	            >
152	              <Block gap={8} align="center">
153	                <Text size={TextSize.large} color={Colors.white}>
154	                  Sign Out
155	                </Text>
156	                <Text font="InstrumentSans-Regular">
157	                  Are you sure you want to sign out?
158	                </Text>
159	              </Block>
160	              <Block gap={12} width="100%" paddings={[0, 52]}>
161	                <Button.Warning onPress={handleSignOut}>
162	                  Sign Out
163	                </Button.Warning>
164	                <Button.Ghost onPress={handleCancel}>Cancel</Button.Ghost>
165	              </Block>
166	            </Block>
167	          )}
168	        </BottomSheetView>
169	      </AppBottomSheet>
170	    </>
171	  );
172	};
