48	const formatDurationMs = (ms?: number) => {
49	  if (!ms || ms <= 0) return "—";
50	  const totalSeconds = Math.round(ms / 1000);
51	  const minutes = Math.floor(totalSeconds / 60);
52	  const seconds = totalSeconds % 60;
53	  return `${minutes}:${seconds.toString().padStart(2, "0")}`;
54	};
