22	const ROOM_ADDRESS_REGEX = /^#.+:.+$/;
23	
24	export const JoinRoom: FC<Props> = ({
25	  isBottomSheetOpen,
26	  setIsBottomSheetOpen,
27	}) => {
28	  const [roomAddress, setRoomAddress] = useState("");
29	  const [loading, setLoading] = useState(false);
30	  const [error, setError] = useState<string | null>(null);
31	  const sheetRef = useRef<AppBottomSheetRef>(null);
32	
33	  const handleTextChange = (text: string) => {
34	    setRoomAddress(text);
35	    setError(null);
36	  };
37	
38	  const handleClose = useCallback(() => {
39	    setIsBottomSheetOpen(false);
40	    setRoomAddress("");
41	    setError(null);
42	  }, [setIsBottomSheetOpen]);
43	
44	  const handleCloseOnPress = useCallback(() => {
45	    sheetRef.current?.close();
46	  }, []);
47	
48	  const handleJoinRoom = useCallback(async () => {
49	    const trimmedAddress = roomAddress.trim();
50	
51	    if (!trimmedAddress) {
52	      setError("Please enter a room address.");
53	      return;
54	    }
55	
56	    if (!ROOM_ADDRESS_REGEX.test(trimmedAddress)) {
57	      setError("Enter a valid room address.");
58	      return;
59	    }
60	
61	    setLoading(true);
62	    setError(null);
63	
64	    try {
